        // o tamanho NOVO) — mantém a âncora exatamente parada no lugar E na
        // MESMA proporção (tX/tY) dentro do retângulo novo.
        const signX = flipH ? -1 : 1, signY = flipV ? -1 : 1;
        const offsetX = signX * (0.5 - drag.tX) * newW;
